    @Test
    public void testIsKeyword_Length9() {
        assertTrue("interface", TokenStream.isKeyword("interface"));
        assertTrue("protected", TokenStream.isKeyword("protected"));
        assertTrue("transient", TokenStream.isKeyword("transient"));

        // Negative cases for length 9
        assertFalse("interfac", TokenStream.isKeyword("interfac"));
        assertFalse("protecte", TokenStream.isKeyword("protecte"));
    }

    @Test
    public void testIsKeyword_Length10() {
        assertTrue("implements", TokenStream.isKeyword("implements"));
        assertTrue("instanceof", TokenStream.isKeyword("instanceof"));

        // Negative cases for length 10
        assertFalse("implement", TokenStream.isKeyword("implement"));
        assertFalse("instanceofx", TokenStream.isKeyword("instanceofx")); // length 11
    }

    @Test
    public void testIsKeyword_Length12() {
        assertTrue("synchronized", TokenStream.isKeyword("synchronized"));
        assertFalse("synchronize", TokenStream.isKeyword("synchronize"));
    }

    @Test
    public void testIsKeyword_EdgeCases() {
        // Test the "X!=null && X!=s && !X.equals(s)" logic
        // This happens when a partial match is found (e.g., "case" matches "case" but input is "caser")
        // However, the switch is based on length, so "caser" (length 5) would hit case 5.
        // Let's look for a case where length is correct but string is wrong.

        // Length 4, case 'c': 'case' is X. If input is 'caee', c=e, X=null. Returns id=false.
        // If length is 4, case 'c', input 'caze'. c=e, X=null. returns false.

        // To hit the "X!=null && X!=s" logic:
        // Length 4, case 'b', X="byte". If input is "byta", length is 4, but switch 'b' sets X="byte", id=true.
        // Then X="byte", s="byta". X!=s is true. Returns false.
        assertFalse("byta", TokenStream.isKeyword("byta"));
        assertFalse("gote", TokenStream.isKeyword("gote"));
        assertFalse("longy", TokenStream.isKeyword("longy")); // length 5

        // Test length 1, 0, or other lengths not in switch
        assertFalse("a", TokenStream.isKeyword("a"));
        assertFalse("", TokenStream.isKeyword(""));
        assertFalse("abcde", TokenStream.isKeyword("abcde"));
    }
}
